const body = $input.first()?.json || {};
const orders = Array.isArray(body.orders) ? body.orders : [];
const out = [];

function compact(value) {
  const text = String(value ?? '').trim();
  return text || null;
}

function carrierFrom(company) {
  const text = String(company || '').toLowerCase();
  if (text.includes('dpd')) return 'dpd';
  if (text.includes('dhl') || text.includes('deutsche post')) return 'dhl';
  return text ? 'other' : 'unknown';
}

for (const order of orders) {
  const fulfillments = Array.isArray(order.fulfillments) ? order.fulfillments : [];
  for (const fulfillment of fulfillments) {
    const trackingNumbers = Array.isArray(fulfillment.tracking_numbers) && fulfillment.tracking_numbers.length
      ? fulfillment.tracking_numbers
      : [fulfillment.tracking_number].filter(Boolean);
    const trackingUrls = Array.isArray(fulfillment.tracking_urls) ? fulfillment.tracking_urls : [];
    for (let index = 0; index < trackingNumbers.length; index += 1) {
      const trackingNumber = compact(trackingNumbers[index]);
      if (!trackingNumber) continue;
      const carrier = carrierFrom(fulfillment.tracking_company);
      const customerName = compact(String(order.customer?.first_name || '') + ' ' + String(order.customer?.last_name || '')) || compact(order.billing_address?.name);
      const shipment = {
        shipmentKey: 'shopify:' + order.id + ':' + fulfillment.id + ':' + carrier + ':' + trackingNumber,
        source: 'shopify',
        shopifyOrderId: String(order.id || ''),
        shopifyOrderNumber: compact(order.name),
        shopifyFulfillmentId: String(fulfillment.id || ''),
        requestId: compact(order.note_attributes?.find?.((entry) => entry?.name === 'request_id')?.value),
        customerName,
        customerEmail: compact(order.email),
        customerPhone: compact(order.phone || order.customer?.phone || order.billing_address?.phone || order.shipping_address?.phone),
        carrier,
        trackingNumber,
        trackingUrl: compact(trackingUrls[index] || fulfillment.tracking_url),
        destinationCountry: compact(order.shipping_address?.country_code || order.billing_address?.country_code),
        shippedAt: compact(fulfillment.created_at || order.updated_at),
        rawShopify: {
          orderId: order.id || null,
          orderName: order.name || null,
          fulfillmentId: fulfillment.id || null,
          trackingCompany: fulfillment.tracking_company || null,
          fulfillmentStatus: order.fulfillment_status || null
        }
      };

      out.push({
        json: {
          shipment,
          initialEvent: {
            carrier,
            trackingNumber,
            carrierEventId: 'shopify:' + order.id + ':' + fulfillment.id + ':' + trackingNumber,
            statusCode: 'LABEL_PRINTED',
            statusText: 'Sendungsdaten aus Shopify erfasst',
            eventTime: compact(fulfillment.created_at || order.updated_at || order.created_at),
            eventLocation: compact(order.shipping_address?.country_code || order.billing_address?.country_code),
            rawEvent: { source: 'shopify', orderId: order.id || null, fulfillmentId: fulfillment.id || null }
          }
        }
      });
    }
  }
}

return out;

const graph = $input.first()?.json || {};
const source = $('Build Shipment Records').item.json || {};
const shipment = source.shipment || {};
const fulfillment = graph.data?.fulfillment || null;
if (!fulfillment) return [];

const events = Array.isArray(fulfillment.events?.edges)
  ? fulfillment.events.edges.map((edge) => edge?.node).filter(Boolean)
  : [];
const trackingInfo = Array.isArray(fulfillment.trackingInfo) ? fulfillment.trackingInfo : [];
const primaryTracking = trackingInfo.find((entry) => entry?.number === shipment.trackingNumber) || trackingInfo[0] || {};
const carrier = shipment.carrier || primaryTracking.company || 'unknown';
const trackingNumber = shipment.trackingNumber || primaryTracking.number;
if (!trackingNumber) return [];

function compact(value) {
  const text = String(value ?? '').trim();
  return text || null;
}

const eventItems = events.length
  ? events
  : [{
      id: fulfillment.id,
      status: fulfillment.status || fulfillment.displayStatus || 'CONFIRMED',
      message: fulfillment.displayStatus || fulfillment.status || 'Shopify Fulfillment Status',
      happenedAt: fulfillment.deliveredAt || fulfillment.inTransitAt || fulfillment.estimatedDeliveryAt || new Date().toISOString(),
      country: shipment.destinationCountry || null
    }];

return eventItems.map((event) => ({
  json: {
    shipment,
    event: {
      carrier,
      trackingNumber,
      carrierEventId: compact(event.id) || ('shopify-fulfillment:' + shipment.shopifyFulfillmentId + ':' + event.status + ':' + (event.happenedAt || event.createdAt)),
      statusCode: compact(event.status),
      statusText: compact(event.message || event.status || fulfillment.displayStatus),
      eventTime: compact(event.happenedAt || event.createdAt || fulfillment.deliveredAt || fulfillment.inTransitAt || new Date().toISOString()),
      eventLocation: [event.city, event.province, event.country, event.zip].map(compact).filter(Boolean).join(', ') || null,
      rawEvent: {
        source: 'shopify_fulfillment_event',
        fulfillmentId: shipment.shopifyFulfillmentId || null,
        fulfillmentGid: fulfillment.id || null,
        displayStatus: fulfillment.displayStatus || null,
        estimatedDeliveryAt: event.estimatedDeliveryAt || fulfillment.estimatedDeliveryAt || null,
        latitude: event.latitude || null,
        longitude: event.longitude || null
      }
    }
  }
}));

const rows = $input.all()
  .flatMap((item) => Array.isArray(item.json) ? item.json : [item.json])
  .filter(Boolean);

return rows
  .map((row) => row.id)
  .filter(Boolean)
  .map((shipmentId) => ({ json: { p_shipment_id: shipmentId } }));

