function compact(value) {
  const text = String(value ?? '').trim();
  return text || null;
}
function normalizeEmail(value) {
  return String(value || '').trim().toLowerCase().replace(/\.+$/, '');
}
function isValidEmail(value) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalizeEmail(value));
}
function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}
function p(value) { return '<p>' + value + '</p>'; }
function firstName(name) {
  const first = compact(name)?.split(/\s+/)[0] || null;
  return first && first.length >= 2 ? first : null;
}
function trackingLink(url, label) {
  if (!url) return '';
  return '<p><a href="' + escapeHtml(url) + '">' + escapeHtml(label || 'Sendungsverfolgung oeffnen') + '</a></p>';
}
const fabienneSignatureHtml = [
