function customerPickup(row) {
  const email = normalizeEmail(row.recipient_email || row.customer_email || '');
  if (!isValidEmail(email) || email.endsWith('@neontrip.de') || email.endsWith('@neontrip.test')) {
    return internalWarning({ ...row, incident_title: 'Pickup-Kundenmail blockiert', incident_severity: 'high', latest_event_status_text: 'Ungueltige oder interne Kunden-E-Mail: ' + email });
  }
  const name = firstName(row.customer_name);
  const carrier = compact(row.carrier)?.toUpperCase() || 'Versanddienstleister';
  const tracking = compact(row.tracking_number);
  const location = compact(row.latest_event_location);
  const statusText = compact(row.latest_event_status_text);
  const order = compact(row.shopify_order_number);
  const reminder = String(row.notification_key || '').includes(':reminder:');
  const subjectPrefix = reminder ? 'Erinnerung: Ihr NEONTRIP Paket liegt zur Abholung bereit' : 'Ihr NEONTRIP Paket liegt zur Abholung bereit';
  const subject = order ? subjectPrefix + ' (' + order + ')' : subjectPrefix;
  const details = [
    tracking ? '<li><strong>Sendungsnummer:</strong> ' + escapeHtml(tracking) + '</li>' : null,
    carrier ? '<li><strong>Versanddienstleister:</strong> ' + escapeHtml(carrier) + '</li>' : null,
    location ? '<li><strong>Ort laut Sendungsverfolgung:</strong> ' + escapeHtml(location) + '</li>' : null,
    statusText ? '<li><strong>Status:</strong> ' + escapeHtml(statusText) + '</li>' : null,
  ].filter(Boolean).join('');
  const body = [
    p(name ? 'Guten Tag ' + escapeHtml(name) + ',' : 'Guten Tag,'),
    p(reminder ? 'wir moechten Sie kurz daran erinnern, dass Ihr NEONTRIP Paket laut Sendungsverfolgung weiterhin zur Abholung bereitliegt.' : 'laut Sendungsverfolgung liegt Ihr NEONTRIP Paket aktuell zur Abholung bereit.'),
    p('Bitte holen Sie die Sendung zeitnah ab, damit sie nicht an uns zurueckgeschickt wird.'),
    details ? '<ul>' + details + '</ul>' : '',
    trackingLink(row.tracking_url),
    p('Falls Sie dazu Fragen haben, antworten Sie einfach auf diese E-Mail.'),
    p('Viele Gruesse'),
    fabienneSignatureHtml
  ].filter(Boolean).join('\n');
  return { ...base(row), to: email, subject, bodyHtml: body, route: 'customer' };
}
function internalWarning(row) {
  const to = normalizeEmail(row.recipient_type === 'internal' ? row.recipient_email : 'info@neontrip.de') || 'info@neontrip.de';
  const tracking = compact(row.tracking_number) || 'ohne Trackingnummer';
  const title = compact(row.incident_title) || 'Shipping-Problem';
  const facts = [
    ['Incident', title],
    ['Severity', compact(row.incident_severity) || '-'],
    ['Status', compact(row.status) || '-'],
    ['Carrier', compact(row.carrier)?.toUpperCase() || '-'],
    ['Tracking', tracking],
    ['Shopify', compact(row.shopify_order_number) || '-'],
    ['Request-ID', compact(row.request_id) || '-'],
    ['Kunde', compact(row.customer_name) || 'Unbekannt'],
    ['Kunden-E-Mail', compact(row.customer_email) || '-'],
    ['Letztes Event', compact(row.latest_event_status_text) || '-'],
    ['Ort', compact(row.latest_event_location) || '-']
  ];
  const rowsHtml = facts.map(([label, value]) => '<tr><td><strong>' + escapeHtml(label) + '</strong></td><td>' + escapeHtml(value) + '</td></tr>').join('');
  const body = [
    '<p><strong>Shipping-Fruehwarnung</strong></p>',
    p('Diese Sendung hat ein Zustell- oder Ruecklaufproblem. Bitte intern pruefen, bevor der Kunde kontaktiert wird.'),
    '<table>' + rowsHtml + '</table>',
    trackingLink(row.tracking_url, 'Carrier-Tracking oeffnen'),
    row.request_id ? trackingLink('https://ops.neontrip.de/ops/customer-records/shipping?requestId=' + encodeURIComponent(row.request_id), 'Shipping Board oeffnen') : ''
  ].filter(Boolean).join('\n');
  return { ...base(row), to, subject: 'Shipping Warnung: ' + title + ' (' + tracking + ')', bodyHtml: body, route: 'internal' };
}
function base(row) {
  return {
    notificationId: row.notification_id,
    notificationKey: row.notification_key,
    kind: row.kind,
    attempts: row.attempts,
    shipmentId: row.shipment_id,
    incidentId: row.incident_id || null
  };
}

return rows.map((row) => ({ json: row.kind === 'customer_pickup_available' ? customerPickup(row) : internalWarning(row) }));

const rows = $input.all()
  .flatMap((item) => Array.isArray(item.json) ? item.json : [item.json])
  .filter((row) => row && row.alert_key);

return rows.map((row) => ({ json: {
  alertKey: row.alert_key,
  to: row.recipient_email || 'info@neontrip.de',
  subject: row.subject || 'Shipping Monitor: Benachrichtigungen pruefen',
  bodyHtml: row.body_html || '<p>Shipping Monitor Alert ohne Details.</p>',
  issueCount: row.issue_count || 0,
  route: 'internal_monitor'
} }));

const hourText = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Europe/Berlin',
  hour: '2-digit',
  hour12: false,
}).format(new Date());

const hour = Number(hourText);
if (![9, 11, 13].includes(hour)) {
  return [];
}

